sections.code:
variable "name" {
  description = "Name prefix for all resources"
  type        = string
}

variable "cidr_block" {
  description = "VPC CIDR, for example 10.20.0.0/16"
  type        = string
  validation {
    condition     = can(cidrnetmask(var.cidr_block))
    error_message = "cidr_block must be a valid IPv4 CIDR."
  }
}

variable "azs" {
  description = "Availability zones to use"
  type        = list(string)
}

variable "tags" {
  description = "Extra tags merged onto every resource"
  type        = map(string)
  default     = {}
}

module "network_dev" {
  source     = "../modules/network"
  name       = "dev"
  cidr_block = "10.10.0.0/16"
  azs        = ["us-east-1a", "us-east-1b"]
}

module "network_prod" {
  source     = "../modules/network"
  name       = "prod"
  cidr_block = "10.20.0.0/16"
  azs        = ["us-east-1a", "us-east-1b", "us-east-1c"]
  tags       = { CostCenter = "platform" }
}

output "prod_vpc_id" {
  value = module.network_prod.vpc_id
}

module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "~> 5.8"

  name = "platform"
  cidr = "10.20.0.0/16"
  azs  = ["us-east-1a", "us-east-1b"]
  private_subnets = ["10.20.1.0/24", "10.20.2.0/24"]
  public_subnets  = ["10.20.101.0/24", "10.20.102.0/24"]
  enable_nat_gateway = true
  single_nat_gateway = true
}

module "baseline" {
  source = "git::https://github.com/acme/terraform-aws-baseline.git?ref=v1.4.2"
}

module "tags" {
  source = "./modules/tags"
}

resource "aws_s3_bucket" "tfstate" {
  bucket = "acme-tfstate-123456789012-us-east-1"
  lifecycle { prevent_destroy = true }
}

resource "aws_s3_bucket_versioning" "tfstate" {
  bucket = aws_s3_bucket.tfstate.id
  versioning_configuration { status = "Enabled" }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "tfstate" {
  bucket = aws_s3_bucket.tfstate.id
  rule {
    apply_server_side_encryption_by_default { sse_algorithm = "aws:kms" }
  }
}

resource "aws_s3_bucket_public_access_block" "tfstate" {
  bucket                  = aws_s3_bucket.tfstate.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

terraform {
  required_version = ">= 1.10"

  backend "s3" {
    bucket       = "acme-tfstate-123456789012-us-east-1"
    key          = "prod/network/terraform.tfstate"
    region       = "us-east-1"
    encrypt      = true
    use_lockfile = true
    # dynamodb_table = "acme-tflocks"   # legacy locking, deprecated
  }
}

resource "aws_instance" "app" {      # was: aws_instance.web
  ami           = "ami-0abcdef1234567890"
  instance_type = "t3.small"
}

moved {
  from = aws_instance.web
  to   = aws_instance.app
}

moved {
  from = aws_s3_bucket.logs
  to   = module.logging.aws_s3_bucket.this
}

import {
  to = aws_s3_bucket.legacy
  id = "acme-legacy-assets"
}

resource "aws_s3_bucket" "legacy" {
  bucket = "acme-legacy-assets"
}

removed {
  from = aws_db_instance.old_reporting

  lifecycle {
    destroy = false
  }
}

variables {
  name       = "test"
  cidr_block = "10.99.0.0/16"
  azs        = ["us-east-1a", "us-east-1b"]
}

run "creates_one_subnet_per_az" {
  command = plan

  assert {
    condition     = length(aws_subnet.private) == 2
    error_message = "Expected one private subnet per AZ."
  }
}

run "rejects_bad_cidr" {
  command = plan
  variables { cidr_block = "nonsense" }
  expect_failures = [var.cidr_block]
}

resource "aws_iam_openid_connect_provider" "github" {
  url            = "https://token.actions.githubusercontent.com"
  client_id_list = ["sts.amazonaws.com"]
}

data "aws_iam_policy_document" "trust_apply" {
  statement {
    actions = ["sts:AssumeRoleWithWebIdentity"]
    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }
    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = ["sts.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:sub"
      values   = ["repo:acme/infrastructure:ref:refs/heads/main"]
    }
  }
}

resource "aws_iam_role" "terraform_apply" {
  name               = "terraform-apply"
  assume_role_policy = data.aws_iam_policy_document.trust_apply.json
}

variable "db_admin_user" {
  type      = string
  sensitive = true
}

resource "random_password" "db" {
  length  = 32
  special = false
}

resource "aws_secretsmanager_secret" "db" {
  name = "prod/app/db"
}

resource "aws_secretsmanager_secret_version" "db" {
  secret_id     = aws_secretsmanager_secret.db.id
  secret_string = random_password.db.result
}

data "aws_iam_policy_document" "plan_state_read" {
  statement {
    actions   = ["s3:GetObject", "s3:ListBucket"]
    resources = [
      "arn:aws:s3:::acme-tfstate-123456789012-us-east-1",
      "arn:aws:s3:::acme-tfstate-123456789012-us-east-1/prod/*",
    ]
  }
}

data "aws_eks_cluster" "this" {
  name = "prod-use1"
}

provider "kubernetes" {
  host                   = data.aws_eks_cluster.this.endpoint
  cluster_ca_certificate = base64decode(data.aws_eks_cluster.this.certificate_authority[0].data)

  exec {
    api_version = "client.authentication.k8s.io/v1beta1"
    command     = "aws"
    args        = ["eks", "get-token", "--cluster-name", "prod-use1"]
  }
}

provider "helm" {
  kubernetes {
    host                   = data.aws_eks_cluster.this.endpoint
    cluster_ca_certificate = base64decode(data.aws_eks_cluster.this.certificate_authority[0].data)
    exec {
      api_version = "client.authentication.k8s.io/v1beta1"
      command     = "aws"
      args        = ["eks", "get-token", "--cluster-name", "prod-use1"]
    }
  }
}

resource "kubernetes_namespace_v1" "ingress" {
  metadata {
    name   = "ingress-nginx"
    labels = { "pod-security.kubernetes.io/enforce" = "baseline" }
  }
}

resource "helm_release" "ingress_nginx" {
  name             = "ingress-nginx"
  repository       = "https://kubernetes.github.io/ingress-nginx"
  chart            = "ingress-nginx"
  version          = "4.11.3"
  namespace        = kubernetes_namespace_v1.ingress.metadata[0].name
  atomic           = true
  timeout          = 600

  values = [yamlencode({
    controller = {
      replicaCount = 2
      service      = { type = "LoadBalancer" }
    }
  })]
}
